     1	package shop;
     2	
     3	import io.javalin.Javalin;
     4	import shop.checkout.CheckoutCalculator;
     5	import shop.coupon.Buy3Pay2Coupon;
     6	import shop.coupon.Coupon;
     7	import shop.coupon.FreeShippingCoupon;
     8	import shop.coupon.Minus50Coupon;
     9	import shop.coupon.Welcome10Coupon;
    10	import shop.notification.Notifier;
    11	import shop.order.CreditReaction;
    12	import shop.order.OrderService;
    13	import shop.order.PaymentApprovedNoticeReaction;
    14	import shop.payment.BankSlipPayment;
    15	import shop.payment.CreditCardPayment;
    16	import shop.payment.PaymentOption;
    17	import shop.payment.PixPayment;
    18	import shop.persistence.Store;
    19	import shop.shipping.CarrierGateway;
    20	import shop.shipping.CarrierShipping;
    21	import shop.shipping.CourierShipping;
    22	import shop.shipping.ShippingOption;
    23	import shop.shipping.StorePickupShipping;
    24	import shop.web.Routes;
    25	
    26	import java.time.Clock;
    27	import java.util.List;
    28	import java.util.Map;
    29	import java.util.function.Function;
    30	import java.util.stream.Collectors;
    31	
    32	/** Wires the service together. Adding a shipping option, coupon, payment method or payment reaction is a line here. */
    33	public final class App {
    34	    private App() {
    35	    }
    36	
    37	    public static Javalin create(Store store, CarrierGateway translog, Clock clock) {
    38	        Map<String, ShippingOption> shipping = byCode(List.of(
    39	                new CarrierShipping("ECONOMY", "STD", translog),
    40	                new CarrierShipping("EXPRESS", "EXP", translog),
    41	                new StorePickupShipping(),
    42	                new CourierShipping()), ShippingOption::code);
    43	        Map<String, Coupon> coupons = byCode(List.of(
    44	                new Welcome10Coupon(), new Minus50Coupon(), new FreeShippingCoupon(), new Buy3Pay2Coupon()), Coupon::code);
    45	        Map<String, PaymentOption> payments = byCode(List.of(
    46	                new PixPayment(), new CreditCardPayment(), new BankSlipPayment()), PaymentOption::code);
    47	
    48	        Notifier notifier = new Notifier();
    49	        OrderService orders = new OrderService(store, new CheckoutCalculator(shipping, coupons, payments), notifier,
    50	                List.of(new CreditReaction(), new PaymentApprovedNoticeReaction(notifier)), clock);
    51	
    52	        Javalin app = Javalin.create();
    53	        new Routes(orders, new QueryService(store)).register(app);
    54	        return app;
    55	    }
    56	
    57	    private static <T> Map<String, T> byCode(List<T> items, Function<T, String> code) {
    58	        return items.stream().collect(Collectors.toUnmodifiableMap(code, Function.identity()));
    59	    }
    60	}
