=== QueryService.java
     1	package shop;
     2	
     3	import shop.catalog.Product;
     4	import shop.customer.Customer;
     5	import shop.notification.Notification;
     6	import shop.notification.NotificationStatus;
     7	import shop.persistence.Store;
     8	
     9	import java.util.List;
    10	
    11	/** Simple lookups: products, customers and their notifications. */
    12	public final class QueryService {
    13	    private final Store store;
    14	
    15	    public QueryService(Store store) {
    16	        this.store = store;
    17	    }
    18	
    19	    public Product product(String sku) {
    20	        return store.inTransaction(tx -> tx.products().find(sku)
    21	                .orElseThrow(() -> ApiException.notFound("PRODUCT_NOT_FOUND")));
    22	    }
    23	
    24	    public Customer customer(String cpf) {
    25	        return store.inTransaction(tx -> tx.customers().find(cpf)
    26	                .orElseThrow(() -> ApiException.notFound("CUSTOMER_NOT_FOUND")));
    27	    }
    28	
    29	    public List<Notification> notifications(String cpf) {
    30	        return store.inTransaction(tx -> {
    31	            tx.customers().find(cpf).orElseThrow(() -> ApiException.notFound("CUSTOMER_NOT_FOUND"));
    32	            return tx.notifications().findByCustomer(cpf);
    33	        });
    34	    }
    35	
    36	    public Notification markRead(String id) {
    37	        return store.inTransaction(tx -> {
    38	            Notification notification = tx.notifications().find(id)
    39	                    .orElseThrow(() -> ApiException.notFound("NOTIFICATION_NOT_FOUND"));
    40	            tx.notifications().markRead(id);
    41	            return new Notification(notification.id(), notification.type(), notification.orderId(),
    42	                    NotificationStatus.READ, notification.customerCpf());
    43	        });
    44	    }
    45	}
