    40	                : installments.isIntegralNumber() && installments.canConvertToInt() ? installments.intValue() : 0;
    41	        return new CheckoutRequest(
    42	                text(customer, "cpf"), text(customer, "email"), items,
    43	                text(body, "zipCode"), text(body, "region"), text(body, "shippingMethod"),
