    23	/** The only place that computes the purchase summary, used both by the preview and by order registration. */
    24	public final class CheckoutCalculator {
    25	    private static final Pattern ZIP = Pattern.compile("\\d{8}");
    26	    private static final BigDecimal COUPON_CEILING = new BigDecimal("0.30");
    27	
    28	    private final Map<String, ShippingOption> shippingOptions;
    29	    private final Map<String, Coupon> coupons;
    30	    private final Map<String, PaymentOption> paymentOptions;
    31	
    32	    public CheckoutCalculator(Map<String, ShippingOption> shippingOptions, Map<String, Coupon> coupons,
    33	                              Map<String, PaymentOption> paymentOptions) {
    34	        this.shippingOptions = shippingOptions;
    35	        this.coupons = coupons;
    36	        this.paymentOptions = paymentOptions;
    37	    }
    38	
    39	    public Summary calculate(Tx tx, CheckoutRequest request) {
    40	        validateShape(request);
    41	        List<CartLine> lines = loadLines(tx, request);
    42	
    43	        ClubTier tier = parse(ClubTier.class, request.clubTier(), "INVALID_CLUB_TIER");
    44	        Region region = parse(Region.class, request.region(), "INVALID_REGION");
    45	        if (request.zipCode() == null || !ZIP.matcher(request.zipCode()).matches()) {
    46	            throw ApiException.unprocessable("INVALID_ZIP_CODE");
    47	        }
    48	        ShippingOption shipping = request.shippingMethod() == null ? null : shippingOptions.get(request.shippingMethod());
    49	        if (shipping == null) {
    50	            throw ApiException.unprocessable("INVALID_SHIPPING_METHOD");
    51	        }
    52	
    53	        BigDecimal subtotal = Money.ZERO;
    54	        BigDecimal weightKg = BigDecimal.ZERO;
    55	        for (CartLine line : lines) {
    56	            subtotal = subtotal.add(line.total());
    57	            weightKg = weightKg.add(line.weightKg());
    58	        }
    59	        subtotal = Money.round(subtotal);
    60	
    61	        ShippingQuote quote = shipping.quote(new ShippingContext(request.zipCode(), region, weightKg));
    62	        BigDecimal shippingCost = tier.waivesShipping() && shipping.acceptsClubFreeShipping()
    63	                ? Money.ZERO : Money.round(quote.cost());
    64	        BigDecimal insurance = region.insurance(subtotal);
    65	
    66	        BigDecimal discount = Money.ZERO;
    67	        if (request.coupon() != null) {
    68	            Coupon coupon = coupons.get(request.coupon());
    69	            if (coupon == null) {
    70	                throw ApiException.unprocessable("INVALID_COUPON");
    71	            }
    72	            BigDecimal raw = coupon.discount(new CouponContext(lines, subtotal, shippingCost, shipping.hasShipping(),
    73	                    () -> !tx.orders().hasConfirmedPurchase(request.cpf())));
    74	            BigDecimal ceiling = Money.round(subtotal.multiply(COUPON_CEILING));
    75	            discount = Money.round(raw.min(ceiling));
    76	        }
    77	
    78	        PaymentOption payment = request.paymentMethod() == null ? null : paymentOptions.get(request.paymentMethod());
    79	        if (payment == null) {
    80	            throw ApiException.unprocessable("INVALID_PAYMENT_METHOD");
    81	        }
    82	        if (!payment.acceptsInstallments(request.installments())) {
    83	            throw ApiException.unprocessable("INVALID_INSTALLMENTS");
    84	        }
    85	        BigDecimal orderTotal = Money.round(subtotal.subtract(discount).add(shippingCost).add(insurance));
    86	        if (!payment.availableFor(orderTotal)) {
    87	            throw ApiException.unprocessable("PAYMENT_METHOD_UNAVAILABLE");
    88	        }
    89	        PaymentCharge charge = payment.charge(orderTotal, request.installments(), request.coupon() != null);
    90	
    91	        return new Summary(subtotal, discount, shippingCost, quote.days(), insurance,
    92	                charge.finalTotal().subtract(orderTotal), charge.finalTotal(), request.installments(),
    93	                charge.installmentAmount(), tier.nextPurchaseCredit(subtotal), tier.gift(subtotal));
    94	    }
    95	
    96	    private static void validateShape(CheckoutRequest request) {
    97	        boolean valid = request.cpf() != null && !request.cpf().isBlank()
    98	                && request.email() != null && !request.email().isBlank()
    99	                && request.items() != null && !request.items().isEmpty();
   100	        if (valid) {
   101	            Set<String> seen = new HashSet<>();
   102	            for (CheckoutRequest.Item item : request.items()) {
   103	                if (item.sku() == null || item.sku().isBlank() || item.quantity() == null || item.quantity() <= 0
   104	                        || !seen.add(item.sku())) {
   105	                    valid = false;
   106	                    break;
   107	                }
   108	            }
   109	        }
   110	        if (!valid) {
   111	            throw ApiException.unprocessable("INVALID_ORDER");
   112	        }
   113	    }
   114	
   115	    private static List<CartLine> loadLines(Tx tx, CheckoutRequest request) {
   116	        List<CartLine> lines = new ArrayList<>();
   117	        for (CheckoutRequest.Item item : request.items()) {
   118	            Product product = tx.products().find(item.sku())
   119	                    .orElseThrow(() -> ApiException.unprocessable("UNKNOWN_PRODUCT"));
   120	            lines.add(new CartLine(product, item.quantity()));
   121	        }
   122	        if (lines.stream().anyMatch(line -> line.product().discontinued())) {
   123	            throw ApiException.unprocessable("PRODUCT_DISCONTINUED");
   124	        }
   125	        if (lines.stream().anyMatch(line -> line.product().stock() < line.quantity())) {
   126	            throw ApiException.unprocessable("INSUFFICIENT_STOCK");
   127	        }
   128	        return lines;
   129	    }
   130	
   131	    private static <E extends Enum<E>> E parse(Class<E> type, String value, String errorCode) {
   132	        if (value != null) {
   133	            for (E constant : type.getEnumConstants()) {
   134	                if (constant.name().equals(value)) {
   135	                    return constant;
   136	                }
   137	            }
   138	        }
   139	        throw ApiException.unprocessable(errorCode);
   140	    }
   141	}
