    27	    public static CheckoutRequest from(JsonNode body) {
    28	        JsonNode customer = body.path("customer");
    29	        List<Item> items = null;
    30	        if (body.path("items").isArray()) {
    31	            items = new ArrayList<>();
    32	            for (JsonNode item : body.get("items")) {
    33	                items.add(new Item(text(item, "sku"), quantity(item.get("quantity"))));
    34	            }
    35	        }
    36	        JsonNode coupon = body.get("coupon");
    37	        String couponCode = coupon == null || coupon.isNull() ? null : coupon.isTextual() ? coupon.asText() : coupon.toString();
    38	        JsonNode installments = body.get("installments");
    39	        int count = installments == null || installments.isNull() ? 1
    40	                : installments.isIntegralNumber() && installments.canConvertToInt() ? installments.intValue() : 0;
    41	        return new CheckoutRequest(
    42	                text(customer, "cpf"), text(customer, "email"), items,
    43	                text(body, "zipCode"), text(body, "region"), text(body, "shippingMethod"),
