    65	    public static void init(DataSource dataSource) throws SQLException {
    66	        try (Connection connection = dataSource.getConnection()) {
    67	            connection.setAutoCommit(true);
    68	            try (PreparedStatement lock = connection.prepareStatement("SELECT pg_advisory_lock(?)")) {
    69	                lock.setLong(1, LOCK_KEY);
    70	                lock.execute();
    71	            }
    72	            try {
    73	                try (Statement statement = connection.createStatement()) {
    74	                    for (String ddl : DDL) {
    75	                        statement.execute(ddl);
    76	                    }
    77	                }
    78	                for (Product product : InitialCatalog.PRODUCTS) {
    79	                    try (PreparedStatement insert = connection.prepareStatement(
    80	                            "INSERT INTO products (sku, name, price, weight_kg, stock, discontinued) "
    81	                                    + "VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT (sku) DO NOTHING")) {
    82	                        insert.setString(1, product.sku());
    83	                        insert.setString(2, product.name());
    84	                        insert.setBigDecimal(3, product.price());
    85	                        insert.setBigDecimal(4, product.weightKg());
    86	                        insert.setInt(5, product.stock());
    87	                        insert.setBoolean(6, product.discontinued());
    88	                        insert.executeUpdate();
    89	                    }
    90	                }
    91	            } finally {
    92	                try (PreparedStatement unlock = connection.prepareStatement("SELECT pg_advisory_unlock(?)")) {
    93	                    unlock.setLong(1, LOCK_KEY);
    94	                    unlock.execute();
    95	                }
    96	            }
    97	        }
    98	    }
