    13	/** Creates what the service needs in an empty database and loads the initial catalog. Safe to run on two machines at once. */
    14	public final class Schema {
    15	    private static final long LOCK_KEY = 7_340_011L;
    16	
    17	    private static final List<String> DDL = List.of(
    18	            """
    19	            CREATE TABLE IF NOT EXISTS products (
    20	                sku text PRIMARY KEY,
    21	                name text NOT NULL,
    22	                price numeric(12,2) NOT NULL,
    23	                weight_kg numeric(10,2) NOT NULL,
    24	                stock integer NOT NULL CHECK (stock >= 0),
    25	                discontinued boolean NOT NULL)""",
    26	            """
    27	            CREATE TABLE IF NOT EXISTS customers (
    28	                cpf text PRIMARY KEY,
    29	                credit_balance numeric(12,2) NOT NULL DEFAULT 0)""",
    30	            """
    31	            CREATE TABLE IF NOT EXISTS orders (
    32	                id text PRIMARY KEY,
    33	                customer_cpf text NOT NULL REFERENCES customers(cpf),
    34	                email text NOT NULL,
    35	                status text NOT NULL,
    36	                created_at timestamptz NOT NULL,
    37	                summary text NOT NULL,
    38	                tracking_code text)""",
    39	            "CREATE INDEX IF NOT EXISTS orders_customer_idx ON orders (customer_cpf, status)",
    40	            """
    41	            CREATE TABLE IF NOT EXISTS order_items (
    42	                order_id text NOT NULL REFERENCES orders(id),
    43	                sku text NOT NULL,
    44	                quantity integer NOT NULL,
    45	                PRIMARY KEY (order_id, sku))""",
    46	            """
    47	            CREATE TABLE IF NOT EXISTS notifications (
    48	                seq bigserial PRIMARY KEY,
    49	                id text NOT NULL UNIQUE,
    50	                customer_cpf text NOT NULL,
    51	                type text NOT NULL,
    52	                order_id text NOT NULL,
    53	                status text NOT NULL)""",
    54	            "CREATE INDEX IF NOT EXISTS notifications_customer_idx ON notifications (customer_cpf, seq)",
    55	            """
    56	            CREATE TABLE IF NOT EXISTS payment_notices (
    57	                order_id text NOT NULL,
    58	                transaction_id text NOT NULL,
    59	                refusal text,
    60	                PRIMARY KEY (order_id, transaction_id))""");
    61	
    62	    private Schema() {
    63	    }
    64	
    65	    public static void init(DataSource dataSource) throws SQLException {
    66	        try (Connection connection = dataSource.getConnection()) {
    67	            connection.setAutoCommit(true);
    68	            try (PreparedStatement lock = connection.prepareStatement("SELECT pg_advisory_lock(?)")) {
    69	                lock.setLong(1, LOCK_KEY);
    70	                lock.execute();
    71	            }
    72	            try {
    73	                try (Statement statement = connection.createStatement()) {
    74	                    for (String ddl : DDL) {
    75	                        statement.execute(ddl);
    76	                    }
    77	                }
    78	                for (Product product : InitialCatalog.PRODUCTS) {
    79	                    try (PreparedStatement insert = connection.prepareStatement(
    80	                            "INSERT INTO products (sku, name, price, weight_kg, stock, discontinued) "
    81	                                    + "VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT (sku) DO NOTHING")) {
    82	                        insert.setString(1, product.sku());
    83	                        insert.setString(2, product.name());
    84	                        insert.setBigDecimal(3, product.price());
    85	                        insert.setBigDecimal(4, product.weightKg());
    86	                        insert.setInt(5, product.stock());
    87	                        insert.setBoolean(6, product.discontinued());
    88	                        insert.executeUpdate();
    89	                    }
    90	                }
    91	            } finally {
    92	                try (PreparedStatement unlock = connection.prepareStatement("SELECT pg_advisory_unlock(?)")) {
    93	                    unlock.setLong(1, LOCK_KEY);
    94	                    unlock.execute();
    95	                }
    96	            }
    97	        }
    98	    }
    99	}
